def derivative(f, a, b):
    return (f(b) - f(a)) / (b - a)

def main():
    x = float(input("Enter a function (lambda): "))
    a = float(input("Enter a: "))
    b = float(input("Enter b: "))

    print("Derivative: ", derivative(x, a, b))

if __name__ == "__main__":
    main()
