  cy.get('body').screenshot(message, { capture: 'fullPage' });
});

Cypress.on('test:done', (test) => {
  if (test.failureCount > 0) {
    const screenshotName = `${test.title}.png`;
    const screenshotPath = path.join(Cypress.env('screenshots'), screenshotName);
    cy.get('body').screenshot(screenshotName);
    fs.writeFileSync(screenshotPath, fs.readFileSync(screenshotPath));
  }
});
