```cpp
#include <string>
#include <regex>

std::string markdown_to_html(const std::string& markdown) {
    std::regex patterns[] = {
        std::regex("\\*(.*?)\\*"),
        std::regex("\\**(.*?)\\**"),
        std::regex("\\<(.*?)\\>"),
        std::regex("\\\\(.*?\\\\)")
    };

    std::string html = markdown;
    for (auto& pattern : patterns) {
        std::string replacement;
        if (pattern == std::regex("\\*(.*?)\\*")) replacement = "<b>$1</b>";
        else if (pattern == std::regex("\\**(.*?)\\**")) replacement = "<strong>$1</strong>";
        else if (pattern == std::regex("\\<(.*?)\\>")) replacement = "<code>$1</code>";
        else if (pattern == std::regex("\\\\(.*?\\\\)")) replacement = "<a href=\"$1\">$1</a>";

        html = std::regex_replace(html, pattern, replacement);
    }

    return html;
}
```

